# than the pool repeats prompts, and over-sampling smaller than the rollout batch under-samples.
def env_int(name, default):
    raw = os.environ.get(name, "")
    if raw.strip() == "":
        return default
    try:
        return int(raw)
    except ValueError as exc:
        raise RuntimeError(f"{name} must be an integer: {raw!r}") from exc

over_sampling = env_int("OVER_SAMPLING_BATCH_SIZE", 64)
rollout_batch = env_int("ROLLOUT_BATCH_SIZE", 16)
if over_sampling > total:
    raise RuntimeError(
        f"OVER_SAMPLING_BATCH_SIZE={over_sampling} exceeds the pool size {total}; "
        f"rollouts would repeat prompts"
    )
if over_sampling < rollout_batch:
    raise RuntimeError(
        f"OVER_SAMPLING_BATCH_SIZE={over_sampling} is smaller than ROLLOUT_BATCH_SIZE={rollout_batch}"
    )

summary = {
    "total": total,
    "source_counts": source_counts,
    "excluded_total": len(excluded_identities),
    "source_pcts": {
        source: round(count * 100 / total) if total else 0
        for source, count in source_counts.items()
    },
}
with open(summary_path, "w", encoding="utf-8") as handle:
    json.dump(summary, handle, sort_keys=True)

print(
    "Validated mixed query pool: "
    f"rows={total} sources={dict(source_counts)} excluded_images={len(excluded_identities)}"
)
