python3 - "${TRAIN_FILE}" "${POOL_MANIFEST}" "${POOL_REGISTRY}" "${_GATE_SUMMARY}" <<'PY'
import json
import os
import sys
from collections import Counter

data_path, manifest_path, registry_path, summary_path = sys.argv[1:]
with open(manifest_path, encoding="utf-8") as handle:
    manifest = json.load(handle)
with open(registry_path, encoding="utf-8") as handle:
    registry_payload = json.load(handle)

expected_tools = ("execute_bash", "think", "complete_plan", "finish")

# The manifest's per-source counts are the requested mix. The builder writes a zero for any
# source at weight 0, and older builders omitted those sources entirely, so both a zero entry
# and an absent entry are legitimate ways of saying "none of this source".
raw_source_counts = manifest.get("source_counts")
if not isinstance(raw_source_counts, dict) or not raw_source_counts:
    raise RuntimeError(f"manifest source_counts must be a non-empty object: {raw_source_counts!r}")
source_counts = {}
for source, count in raw_source_counts.items():
    if isinstance(count, bool) or not isinstance(count, int):
        raise RuntimeError(f"manifest source_counts must contain integer counts: {raw_source_counts!r}")
    if count < 0:
        raise RuntimeError(f"manifest source_counts must be non-negative: {raw_source_counts!r}")
    source_counts[str(source)] = count

# A total that is absent (older schema) is derived from the source counts, which the data is
# checked against. A total that is present must be an integer equal to that sum; anything else
# is malformed and refuses the launch rather than being silently coerced.
raw_total = manifest.get("total_queries")
if raw_total is None:
    total = sum(source_counts.values())
elif isinstance(raw_total, bool) or not isinstance(raw_total, int):
    raise RuntimeError(f"manifest total_queries must be an integer: {raw_total!r}")
else:
    total = raw_total
if total != sum(source_counts.values()):
    raise RuntimeError(
        f"manifest total_queries does not match source_counts: total={total} "
        f"source_sum={sum(source_counts.values())}"
    )

# The registry is repo-wide: it may name sources this pool does not contain, and that is fine.
excluded_identities = []
for item in registry_payload.get("selected", []):
    if not isinstance(item, dict):
        raise RuntimeError(f"invalid registry entry: {item}")
    source = item.get("source")
    instance_id = item.get("instance_id")
    if not source or not instance_id:
        raise RuntimeError(f"invalid registry entry: {item}")
    excluded_identities.append((source, instance_id))
if len(excluded_identities) != len(set(excluded_identities)):
    raise RuntimeError("duplicate source/instance entries in the registry")
excluded_identities = set(excluded_identities)
excluded_counts = Counter(source for source, _ in excluded_identities)

identities = []
data_counts = Counter()
with open(data_path, encoding="utf-8") as handle:
    for line in handle:
        if not line.strip():
            continue
        row = json.loads(line)
        metadata = row.get("metadata") or {}
        source = metadata.get("pool_source")
        instance_id = metadata.get("instance_id")
        identities.append((source, instance_id))
        data_counts[source] += 1
        tool_names = tuple(
            tool.get("function", {}).get("name") or tool.get("name")
            for tool in row.get("tools", [])
        )
        if tool_names != expected_tools:
            raise RuntimeError(f"unexpected tools for {(source, instance_id)}: {tool_names}")

if len(identities) != total or len(set(identities)) != total:
    raise RuntimeError(
        f"expected {total} unique queries, got rows={len(set(identities))} unique={len(set(identities))}"
    )
if dict(data_counts) != source_counts:
    raise RuntimeError(f"unexpected source counts: {dict(data_counts)}")
present_exclusions = sorted(set(identities) & excluded_identities)
if present_exclusions:
    raise RuntimeError(f"unusable instances remain in the query pool: {present_exclusions}")

# The manifest's excluded_instance_counts must agree with the registry, per source it declares.
manifest_excluded_counts = manifest.get("excluded_instance_counts", {})
if not isinstance(manifest_excluded_counts, dict):
    raise RuntimeError(f"manifest excluded_instance_counts must be an object: {manifest_excluded_counts!r}")
for source in source_counts:
    declared = manifest_excluded_counts.get(source, 0)
    if isinstance(declared, bool) or not isinstance(declared, int) or declared != excluded_counts.get(source, 0):
        raise RuntimeError(
            "manifest does not match the unusable-instance registry: "
            f"source={source} manifest={declared!r} registry={excluded_counts.get(source, 0)}"
        )

# The launch case itself can also pin its expectation of what the pool should be; the pool
# on disk is what it is, and a mismatch here means the wrong experiment is about to start.
expected_total_env = os.environ.get("POOL_EXPECTED_TOTAL")
if expected_total_env is not None and expected_total_env != "":
    try:
        case_total = int(expected_total_env)
    except ValueError as exc:
        raise RuntimeError(f"POOL_EXPECTED_TOTAL must be an integer: {expected_total_env!r}") from exc
    if case_total != total:
        raise RuntimeError(f"pool total {total} does not match POOL_EXPECTED_TOTAL={case_total}")

expected_counts_env = os.environ.get("POOL_EXPECTED_SOURCE_COUNTS")
if expected_counts_env is not None and expected_counts_env != "":
    try:
        case_counts = {}
        for item in expected_counts_env.split(","):
            source, sep, raw = item.strip().partition("=")
            if not sep:
                raise ValueError
            case_counts[source.strip()] = int(raw)
    except ValueError as exc:
        raise RuntimeError(f"POOL_EXPECTED_SOURCE_COUNTS malformed: {expected_counts_env!r}") from exc
    if case_counts != source_counts:
        raise RuntimeError(
            f"pool source counts {source_counts} do not match POOL_EXPECTED_SOURCE_COUNTS={case_counts}"
        )

# The rollout batch configuration must describe the pool it will consume: over-sampling wider
# than the pool repeats prompts, and over-sampling smaller than the rollout batch under-samples.
def env_int(name, default):
    raw = os.environ.get(name, "")
    if raw.strip() == "":
        return default
    try:
        return int(raw)
    except ValueError as exc:
        raise RuntimeError(f"{name} must be an integer: {raw!r}") from exc

over_sampling = env_int("OVER_SAMPLING_BATCH_SIZE", 64)
rollout_batch = env_int("ROLLOUT_BATCH_SIZE", 16)
if over_sampling > total:
    raise RuntimeError(
        f"OVER_SAMPLING_BATCH_SIZE={over_sampling} exceeds the pool size {total}; "
        f"rollouts would repeat prompts"
    )
if over_sampling < rollout_batch:
    raise RuntimeError(
        f"OVER_SAMPLING_BATCH_SIZE={over_sampling} is smaller than ROLLOUT_BATCH_SIZE={rollout_batch}"
    )

summary = {
    "total": total,
    "source_counts": source_counts,
    "excluded_total": len(excluded_identities),
    "source_pcts": {
        source: round(count * 100 / total) if total else 0
        for source, count in source_counts.items()
    },
}
with open(summary_path, "w", encoding="utf-8") as handle:
    json.dump(summary, handle, sort_keys=True)

print(
    "Validated mixed query pool: "
    f"rows={total} sources={dict(source_counts)} excluded_images={len(excluded_identities)}"
)
PY
